SELECT p.id AS position_id, p.closed_at, s.interval_code, s.id, s.candle_open_time, s.generated_at, TIMESTAMPDIFF(SECOND, s.generated_at, p.closed_at) AS age_at_close_s, s.decision, s.original_decision, s.total_score, s.confidence_score, s.latest_price FROM paper_position p JOIN trade_signal s ON s.id = (SELECT s2.id FROM trade_signal s2 WHERE s2.symbol=p.symbol AND s2.interval_code=iv.code AND s2.generated_at <= p.closed_at ORDER BY s2.generated_at DESC LIMIT 1) JOIN (SELECT '1m' AS code UNION ALL SELECT '5m' UNION ALL SELECT '1h') iv ON iv.code=s.interval_code WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, s.interval_code